sys_variable_value.value:
(function execute(inputs, outputs) {
    var logPrefix = ">>> [MATCH_ACTION_DEBUG] ";

    // 1. Extreme Cleaning for Inputs
    var cleanInput = function(val) {
        if (!val) return "";
        return val.toString().trim().replace(/[\u200B-\u200D\uFEFF]/g, "");
    };

    var targetQtyRaw = cleanInput(inputs.quantity);
    var targetPPURaw = cleanInput(inputs.ppu);
    var period = cleanInput(inputs.performance_period);
    var companyId = inputs.company; 

    gs.info(logPrefix + "Inputs Received - Qty: " + targetQtyRaw + " | PPU: " + targetPPURaw + " | Period: " + period + " | Company: " + companyId);

    // 2. Math Conversion for Quantity
    var cleanMathNumber = function(s) {
        if (!s) return 0;
        var cleanS = s;
        if (s.indexOf(',') > -1) cleanS = s.replace(/\./g, '').replace(',', '.');
        var parsed = parseFloat(cleanS) || 0;
        return parsed;
    };

    // 3. Format PPU for String Match
    var formatPPUForDB = function(s) {
        var num = parseFloat(s.replace(',', '.'));
        if (isNaN(num)) return s;
        var parts = num.toFixed(2).split('.');
        parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".");
        return parts.join(',');
    };

    var targetQty = cleanMathNumber(targetQtyRaw);
    var targetPPU = formatPPUForDB(targetPPURaw);
    
    gs.info(logPrefix + "Processed Values - targetQty: " + targetQty + " | targetPPU: " + targetPPU);

    var totalHours = 0;
    var matchedTasks = [];
    var userCandidates = {};

    // 4. Date Setup
    var dateParts = period.split("-");
    if (dateParts.length >= 2) {
        var startStr = dateParts[0] + "-" + dateParts[1] + "-01 00:00:00";
        var gdtStart = new GlideDateTime(startStr);
        var gdtEnd = new GlideDateTime(startStr);
        gdtEnd.addMonthsLocalTime(1);
        gdtEnd.addSeconds(-1);

        gs.info(logPrefix + "Query Dates - Start: " + gdtStart.getValue() + " | End: " + gdtEnd.getValue());

        // 5. Query
        var taskGR = new GlideRecord('task');
        taskGR.addQuery('company', companyId);
        taskGR.addQuery('assigned_to.u_price_per_unit', targetPPU);
        taskGR.addQuery('due_date', '>=', gdtStart);
        taskGR.addQuery('due_date', '<=', gdtEnd);
        
        gs.info(logPrefix + "Encoded Query: " + taskGR.getEncodedQuery());
        
        taskGR.query();
        gs.info(logPrefix + "Query Row Count: " + taskGR.getRowCount());

        while (taskGR.next()) {
            var durationMS = taskGR.time_worked.getGlideObject().getNumericValue();
            var hours = (durationMS / 3600000);
            
            gs.info(logPrefix + "Found Task: " + taskGR.number + " | Hours: " + hours.toFixed(4));

            if (durationMS > 0) {
                totalHours += hours;
                matchedTasks.push(taskGR.getUniqueValue().toString());
                var userId = taskGR.assigned_to.toString();
                userCandidates[userId] = taskGR.assigned_to.getDisplayValue();
            }
        }
    } else {
        gs.error(logPrefix + "Invalid Period format: " + period);
    }

    // 6. Outputs
    outputs.total_hours_found = totalHours.toFixed(2);
    outputs.match_found = (Math.abs(totalHours - targetQty) < 0.1);
    outputs.matched_task_array = matchedTasks;
    
    var userIds = Object.keys(userCandidates);
    outputs.user_who_worked = userIds.length === 1 ? userIds[0] : "";
    outputs.status = "Flow Run - PPU Used: [" + targetPPU + "] | Hours: " + totalHours.toFixed(2);

    gs.info(logPrefix + "Final Results - Total Hours: " + outputs.total_hours_found + " | Match: " + outputs.match_found + " | Task Count: " + matchedTasks.length);

})(inputs, outputs);

